def helper_check_space_names(name):
    if name is None:
        return False
    return ' ' in str(name) or '-' in str(name)

def hook(ctx, nb):
    task = ctx.get('task', {})
    target_table = task.get('target_table', '')
    hint_text = ''
    if helper_check_space_names(target_table):
        hint_text = 'Table or column names may contain spaces. Always use backticks around identifiers like `Table Name` and `Column Name` in SQL queries.'
        return {'skills': [{'text': hint_text}], 'tool_hint': hint_text}
    return None

def helper_update_error_state(ctx, nb):
    predicates = ctx.get('predicates', {})
    state = ctx.get('state', {})
    if predicates.get('syntax_error', False):
        nb['fixing_syntax'] = True
        nb['syntax_error_count'] = nb.get('syntax_error_count', 0) + 1
    if predicates.get('unknown_column_error', False):
        nb['fixing_unknown_column'] = True
        nb['unknown_col_count'] = nb.get('unknown_col_count', 0) + 1
    if predicates.get('last_result_empty', False):
        nb['empty_streak'] = nb.get('empty_streak', 0) + 1
    else:
        nb['empty_streak'] = 0
    if state.get('last_result_was_error', False) is False and state.get('last_result') is not None:
        nb['schema_probed'] = True
    return None

def hook(ctx, nb):
    helper_update_error_state(ctx, nb)
    return None

def helper_build_recovery_hint(ctx, nb):
    predicates = ctx.get('predicates', {})
    task = ctx.get('task', {})
    target_table = task.get('target_table', 'table')
    safe_table = '`' + target_table + '`' if ' ' in target_table else target_table
    if nb.get('fixing_syntax', False) and nb.get('syntax_error_count', 0) >= 2:
        return {'message': 'Repeated syntax errors. Verify table exists with SHOW TABLES. Use DESCRIBE ' + safe_table + ' to check exact column names. Wrap all identifiers with spaces in backticks.'}
    if nb.get('fixing_unknown_column', False):
        return {'message': 'Unknown column detected. Run DESCRIBE ' + safe_table + ' to see actual column names, then use backticks for columns containing spaces.'}
    if nb.get('empty_streak', 0) >= 2 and nb.get('schema_probed', False) is False:
        return {'message': 'Multiple empty results. Probe schema with DESCRIBE ' + safe_table + ' and inspect sample data with SELECT * FROM ' + safe_table + ' LIMIT 5.'}
    last_hint = nb.get('last_hint', '')
    new_hint = ''
    if nb.get('empty_streak', 0) >= 3:
        new_hint = 'Still getting empty results. Check if filter conditions match actual data format. Try removing WHERE clause to see available values.'
    if new_hint and new_hint != last_hint:
        nb['last_hint'] = new_hint
        return {'message': new_hint}
    return None

def hook(ctx, nb):
    return helper_build_recovery_hint(ctx, nb)
